import java.util.*;

class MaxStack {
  private final Deque<Integer> stack = new ArrayDeque<>();
  private final TreeMap<Integer, Integer> counts = new TreeMap<>();

  public MaxStack() {}

  public void push(int x) {
    stack.push(x);
    counts.put(x, counts.getOrDefault(x, 0) + 1);
  }

  public int pop() {
    int value = stack.pop();
    removeCount(value);
    return value;
  }

  public int top() {
    return stack.peek();
  }

  public int peekMax() {
    return counts.lastKey();
  }

  public int popMax() {
    int maximum = counts.lastKey();
    Deque<Integer> buffer = new ArrayDeque<>();
    while (stack.peek() != maximum) buffer.push(stack.pop());
    stack.pop();
    removeCount(maximum);
    while (!buffer.isEmpty()) stack.push(buffer.pop());
    return maximum;
  }

  private void removeCount(int value) {
    int count = counts.get(value);
    if (count == 1) counts.remove(value);
    else counts.put(value, count - 1);
  }
}
